const signupUnsubscribeAll = `-- name: SignupUnsubscribeAll :many
UPDATE list_memberships
SET status = 'unsubscribed', unsubscribed_at = $1::timestamptz
WHERE contact_id = $2 AND status <> 'unsubscribed'
RETURNING list_id
`

type SignupUnsubscribeAllParams struct {
	At        time.Time `json:"at"`
	ContactID uuid.UUID `json:"contactId"`
}

func (q *Queries) SignupUnsubscribeAll(ctx context.Context, arg SignupUnsubscribeAllParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, signupUnsubscribeAll, arg.At, arg.ContactID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var list_id uuid.UUID
		if err := rows.Scan(&list_id); err != nil {
			return nil, err
		}
		items = append(items, list_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

